{
  "schemaVersion": "0.2",
  "slug": "data-screen",
  "name": "Data screen",
  "status": "experimental",
  "purpose": "Operations canvas with KPI tiles and charts that scale to the parent instead of using viewport media queries.",
  "scenarios": [
    "Scan four KPI tiles on an operations canvas",
    "Compare traffic and conversion charts in a two-column grid",
    "Fit the 1280×720 design canvas to a smaller parent"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "KPI tiles are present." },
    { "name": "empty", "description": "No KPI tiles to show." }
  ],
  "composition": {
    "allowedParents": ["page"],
    "allowedChildren": ["chart", "kpi-dashboard", "grid", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not size this canvas with viewport width media queries.",
    "Do not claim first-paint performance numbers; Block budgets are unapproved."
  ],
  "a11y": {
    "role": "region",
    "keyboard": ["Tab reaches KPI tiles and chart figures"],
    "focus": "Charts expose an accessible name on the SVG.",
    "labeling": "KPI dashboard and both charts have accessible names.",
    "wcag": ["1.1.1", "2.1.1", "4.1.2"]
  },
  "responsive": {
    "strategy": "A 1280×720 stage scales down with ResizeObserver to fit the parent. Layout is designed at desktop size, then scaled.",
    "breakpoints": {
      "compact": "Canvas scales down; layout stays the desktop composition.",
      "medium": "Canvas scales toward 1.",
      "large": "Canvas stays at scale 1 when the parent is at least 1280×720."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "data-screen",
    "states": ["default", "empty"],
    "intents": ["monitor-metrics"]
  }
}

import { Chart, Grid, KpiDashboard, Typography } from '@chameleon-ui/components-react'
import type { ChartSeries, KpiItem } from '@chameleon-ui/components-react'
import { useEffect, useRef, useState } from 'react'
import { createBlockCopy } from '../copy.js'
import { dataScreenLocaleTrees } from './locale-map.js'
import './styles.css'

/** 1280px == breakpoint.desktop at a 16px root. */
export const DATA_SCREEN_DESIGN_INLINE = 1280
/** 720px design canvas. */
export const DATA_SCREEN_DESIGN_BLOCK = 720

export interface DataScreenProps {
  locale?: string
  kpis?: KpiItem[]
  traffic?: ChartSeries[]
  conversions?: ChartSeries[]
  className?: string
}

function defaultKpis(t: (key: string) => string): KpiItem[] {
  return [
    { id: 'sessions', label: t('screen.kpiSessions'), value: t('screen.kpiSessionsValue'), trend: 'up' },
    { id: 'conversion', label: t('screen.kpiConversion'), value: t('screen.kpiConversionValue'), trend: 'up' },
    { id: 'latency', label: t('screen.kpiLatency'), value: t('screen.kpiLatencyValue'), trend: 'down' },
    { id: 'errors', label: t('screen.kpiErrors'), value: t('screen.kpiErrorsValue'), trend: 'flat' },
  ]
}

export function DataScreen({
  locale = 'en',
  kpis,
  traffic,
  conversions,
  className,
}: DataScreenProps) {
  const { t } = createBlockCopy(dataScreenLocaleTrees, locale)
  const viewportRef = useRef<HTMLDivElement>(null)
  const [scale, setScale] = useState(1)
  const classes = ['cu-block-data-screen', className].filter(Boolean).join(' ')
  const items = kpis ?? defaultKpis(t)
  const trafficSeries = traffic ?? [{ name: t('screen.trafficSeries'), data: [12, 18, 16, 22, 28, 24] }]
  const conversionSeries = conversions ?? [{ name: t('screen.conversionSeries'), data: [4, 6, 5, 8, 7, 9] }]
  const panelCount = 2 + (items.length > 0 ? 1 : 0)

  useEffect(() => {
    const viewport = viewportRef.current
    if (!viewport || typeof ResizeObserver === 'undefined') return

    const measure = (width: number, height: number) => {
      if (width <= 0 || height <= 0) return
      setScale(Math.min(width / DATA_SCREEN_DESIGN_INLINE, height / DATA_SCREEN_DESIGN_BLOCK, 1))
    }

    measure(viewport.clientWidth, viewport.clientHeight)
    const observer = new ResizeObserver((entries) => {
      const entry = entries[0]
      if (!entry) return
      measure(entry.contentRect.width, entry.contentRect.height)
    })
    observer.observe(viewport)
    return () => observer.disconnect()
  }, [])

  return (
    <section
      className={classes}
      data-ai-role="data-screen"
      data-ai-intent="monitor-metrics"
      data-ai-state={items.length === 0 ? 'empty' : 'default'}
    >
      <div className="cu-block-data-screen__header">
        <Typography variant="heading-1">{t('screen.title')}</Typography>
        <Typography variant="body">{t('screen.subtitle')}</Typography>
        <p className="cu-block-data-screen__meta">{t('screen.panelCount', { count: panelCount })}</p>
      </div>
      <div
        className="cu-block-data-screen__viewport"
        data-scale={String(scale)}
        ref={viewportRef}
      >
        <div
          className="cu-block-data-screen__stage"
          style={{ transform: `scale(${scale})` }}
        >
          <KpiDashboard items={items} label={t('screen.kpiLabel')} />
          <Grid columns={2} gap="lg">
            <Chart
              emptyLabel={t('screen.emptyLabel')}
              label={t('screen.trafficLabel')}
              series={trafficSeries}
              type="area"
            />
            <Chart
              emptyLabel={t('screen.emptyLabel')}
              label={t('screen.conversionLabel')}
              series={conversionSeries}
              type="bar"
            />
          </Grid>
        </div>
      </div>
    </section>
  )
}

{
  "slug": "data-screen",
  "type": "registry:block",
  "name": "Data screen",
  "dependencies": ["chart", "grid", "kpi-dashboard", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 1280,
    "title": "KPI dashboard and charts on a scaling canvas"
  }
}

.cu-block-data-screen {
  display: grid;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-data-screen__header {
  display: grid;
  gap: var(--cu-space-2);
}

.cu-block-data-screen__meta {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-data-screen__viewport {
  overflow: hidden;
  inline-size: 100%;
  min-block-size: calc(var(--cu-space-3) * 20);
}

.cu-block-data-screen__stage {
  display: grid;
  gap: var(--cu-space-3);
  /* 80rem == breakpoint.desktop (1280px); 45rem == 720px design canvas */
  inline-size: 80rem;
  min-block-size: 45rem;
  transform-origin: top center;
}
